const visible=(q,a)=> (!q.when || [a[q.when[0]]].flat().includes(q.when[1])) && (!q.unless || (a[q.unless[0]] && ![a[q.unless[0]]].flat().includes(q.unless[1])));
const answered=v=>Array.isArray(v)?v.length>0:typeof v==='string'&&v.trim().length>0;
function validate(q,v){if(q.required&&!answered(v))return '回答してください';if(!answered(v))return '';if(['single','multi','design'].includes(q.type)){const opts=q.type==='design'?['白基調','ダーク','ナチュラル','高級感','シンプル','ポップ']:q.options;if(![v].flat().every(x=>opts.includes(x)))return '選択肢を確認してください';}if(q.type==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))return 'メール形式を確認してください';if(q.type==='url'){try{if(!['https:','http:'].includes(new URL(v).protocol))return 'https または http のURLを入力してください'}catch{return 'URLを確認してください'}}return '';}
function payload(schema,a,notes,id,project){return {submissionId:id,projectId:project,schemaVersion:schema.version,answers:schema.questions.filter(q=>visible(q,a)).map(q=>({questionId:q.id,answer:a[q.id]??(q.type==='multi'?[]:''),note:notes[q.id]??''}))};}

