const headers={'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; frame-ancestors 'none'; base-uri 'none'; form-action 'self'"};const json=(o,status=200)=>new Response(JSON.stringify(o),{status,headers:{...headers,'Content-Type':'application/json'}});
export default {async fetch(request,env){let url=new URL(request.url);if(url.pathname==='/api/submit'){if(request.method!=='POST')return json({error:'method'},405);if(request.headers.get('Origin')!==url.origin)return json({error:'origin'},403);if(!env.GAS_URL||!env.GAS_SECRET)return json({ok:false,error:'保存先が未接続です。担当者にご連絡ください。'},503);if(!/^https:\/\/script.google.com\/macros\/s\/[^/]+\/exec$/.test(env.GAS_URL))return json({error:'receiver_configuration'},503);let raw=await request.text();if(raw.length>400000)return json({error:'size'},413);try{let d=JSON.parse(raw);if(d.schemaVersion!==schema.version||!Array.isArray(d.answers)||d.answers.length>200||!/^[-a-zA-Z0-9]{8,80}$/.test(d.submissionId)||!/^[-a-zA-Z0-9]{3,80}$/.test(d.projectId))return json({error:'invalid_payload'},400);let a={},notes={};for(let x of d.answers){if(Object.hasOwn(a,x.questionId)||typeof x.note!=='string'||x.note.length>2000)return json({error:'invalid_answer'},400);a[x.questionId]=x.answer;notes[x.questionId]=x.note;}let qs=schema.questions.filter(q=>visible(q,a));if(qs.length!==d.answers.length||qs.some(q=>!Object.hasOwn(a,q.id)||validate(q,a[q.id])||q.type==='multi'&&(!Array.isArray(a[q.id])||new Set(a[q.id]).size!==a[q.id].length)||q.type!=='multi'&&typeof a[q.id]!=='string'||JSON.stringify(a[q.id]).length>10000))return json({error:'invalid_answers'},400);let r=await fetch(env.GAS_URL,{method:'POST',headers:{'Content-Type':'text/plain'},body:JSON.stringify({...d,secret:env.GAS_SECRET}),signal:AbortSignal.timeout(25000)});let result=await r.json();return json(result,result.ok?200:422)}catch{return json({ok:false,error:'送信先に接続できません。同じ受付IDで再試行してください。'},502)}}if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});let asset=assets[url.pathname==='/'?'/index.html':url.pathname];if(!asset)return new Response('Not found',{status:404});return new Response(request.method==='HEAD'?null:asset.body,{headers:{...headers,'Content-Type':asset.type}})}};